$store=new Database($wpdb);$store->migrate();$store->migrate();ani_check(class_exists('WC_Product'),'WooCommerce active');
$store->query("DELETE FROM {$store->table('jobs')} WHERE module='stock'");$store->query("DELETE FROM {$store->table('stock_requests')}");
