$phone='+989127778888';$store->query($wpdb->prepare("DELETE FROM {$store->table('identities')} WHERE phone=%s",$phone));$store->insert('identities',array('phone'=>$phone,'user_id'=>$user,'verified_at'=>time(),'verification_mode'=>'local'));
