$back=$make();$back->set_backorders('yes');$back->set_stock_status('onbackorder');$back->save();ani_rejects(fn()=>$service->request($back->get_id(),$user,true),'backorders excluded');
$hidden=$make();$hidden->set_catalog_visibility('hidden');$hidden->save();ani_rejects(fn()=>$service->request($hidden->get_id(),$user,true),'hidden product rejected');
$parent=new WC_Product_Variable();$parent->set_name('محصول متغیر تست');$parent->set_status('publish');$parent->save();$v1=$make('variation',$parent->get_id());$v2=$make('variation',$parent->get_id());
ani_rejects(fn()=>$service->request($parent->get_id(),$user,true),'variable parent requires exact variation');$vid=$service->request($v1->get_id(),$user,true);$v2id=$service->request($v2->get_id(),$user,true);$restock($v1);$drain();ani_check('simulated'===$get($vid)['state']&&'waiting'===$get($v2id)['state'],'variation restock never notifies sibling');
$settings=$make();$sid=$service->request($settings->get_id(),$user,true);$restock($settings);$s=Service::settings();$s['template']=999;update_option('ani_sms_stock_settings',$s);$drain();ani_check('cancelled'===$get($sid)['state'],'settings change cancels queued snapshot');$s['template']=0;update_option('ani_sms_stock_settings',$s);
$unknown=$make();$uid=$service->request($unknown->get_id(),$user,true);$restock($unknown);$job=$jobs($uid)[0];$store->query($wpdb->prepare("UPDATE {$store->table('jobs')} SET state='processing',lease=0 WHERE id=%d",$job['id']));$queue->drain();$service->reconcile();ani_check('unknown'===$get($uid)['state'],'interrupted send terminal unknown');$service->capture($unknown->get_id());ani_check(1===count($jobs($uid)),'unknown alert is never blindly retried');
$privacy=new AniSms\Stock\Privacy($store);ani_check(count($privacy->export(get_user_by('id',$user)->user_email)['data'])>0,'privacy export contains requests');
$deleted=$make();$did=$service->request($deleted->get_id(),$user,true);$deleted->delete(true);ani_check(null===$get($did),'product deletion removes related request');
$expired=$make();$eid=$service->request($expired->get_id(),$user,true);$store->query($wpdb->prepare("UPDATE {$store->table('stock_requests')} SET expires=0 WHERE id=%d",$eid));$service->reconcile();ani_check('expired'===$get($eid)['state']&&''===$get($eid)['phone'],'expiry enforced independent of cleanup');
$disabled=$make();$offid=$service->request($disabled->get_id(),$user,true);update_option('ani_sms_modules',array('auth'));ani_check('cancelled'===$get($offid)['state'],'module disable cancels waiting requests');update_option('ani_sms_modules',array('auth','stock'));
ani_check('cancelled'===$get($offid)['state'],'re-enable does not revive requests');
$privacy->erase(get_user_by('id',$user)->user_email);ani_check(0===(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$store->table('stock_requests')} WHERE user_id=%d",$user)),'privacy erasure removes request data');
$mode=$make();$mid=$service->request($mode->get_id(),$user,true);$store->query($wpdb->prepare("UPDATE {$store->table('stock_requests')} SET mode='live' WHERE id=%d",$mid));$restock($mode);ani_check(0===count($jobs($mid)),'local stock event cannot enqueue live request');$mode->delete(true);
$managed=new WC_Product_Variable();$managed->set_name('Parent-managed stock');$managed->set_status('publish');$managed->set_manage_stock(true);$managed->set_stock_quantity(0);$managed->set_stock_status('outofstock');$managed->save();
$child=$make('variation',$managed->get_id());$child->set_manage_stock(false);$child->set_stock_status('outofstock');$child->save();$managedid=$service->request($child->get_id(),$user,true);$managed=wc_get_product($managed->get_id());$restock($managed);
ani_check(false!==wp_next_scheduled('ani_sms_stock_children',array($managed->get_id(),0)),'parent stock event schedules child recovery');$module->children($managed->get_id(),0);ani_check(false!==wp_next_scheduled('ani_sms_stock_scan',array($child->get_id())),'child recovery schedules exact variation scan');$service->capture($child->get_id());$drain();ani_check('simulated'===$get($managedid)['state'],'parent-managed stock notifies exact subscribed variation');$managed->delete(true);
$private=$make();$pid=$service->request($private->get_id(),$user,true);$private->set_status('draft');$private->save();ani_check('cancelled'===$get($pid)['state']&&''===$get($pid)['phone'],'withdrawn product cancels requests and clears phone');$private->delete(true);
$batch=$make();$restock($batch);$secret=new AniSms\Security\Secrets();
for($i=0;$i<51;$i++){$store->insert('stock_requests',array('product_id'=>$batch->get_id(),'user_id'=>900000+$i,'phone'=>$secret->encrypt($phone),'mode'=>'local','state'=>'waiting','revision'=>bin2hex(random_bytes(16)),'created'=>time(),'expires'=>time()+86400));}
$service->capture($batch->get_id());
ani_check(50===(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$store->table('stock_requests')} WHERE product_id=%d AND state='queued'",$batch->get_id())),'fanout handles at most 50 requests per invocation');
ani_check(false!==wp_next_scheduled('ani_sms_stock_scan',array($batch->get_id())),'fanout schedules bounded continuation');$service->capture($batch->get_id());
ani_check(51===(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$store->table('stock_requests')} WHERE product_id=%d AND state='queued'",$batch->get_id())),'continuation drains remaining recipients without duplicates');$batch->delete(true);
ani_rejects(fn()=>Service::validate(array('stock_template'=>0,'stock_mapping'=>'Code=unknown')),'unknown template variable rejected');ani_rejects(fn()=>Service::validate(array('stock_template'=>0,'stock_mapping'=>"Code=site_name\nCode=product_name")),'duplicate template parameter rejected');
ani_check(0===$http,'zero HTTP for local stock tests');require_once ABSPATH.'wp-admin/includes/user.php';wp_delete_user($user);
foreach(array($p,$q,$back,$hidden,$parent,$settings,$unknown,$expired,$disabled)as $product){$product->delete(true);}
echo 'Stock alerts: '.$GLOBALS['ani_checks']." checks passed; no SMS/HTTP\n";
